class PrivateMessageRow extends DataClass
    implements Insertable<PrivateMessageRow> {
  final String id;

  /// 会话对方：旧住民的 id，或者固定住民的 id（v3.0）。
  /// 两张表各自保证 id 唯一，这里不设外键。
  final String personaId;

  /// in = 住民发给我的，out = 我发出去的
  final String direction;
  final String content;

  /// text / voice / sticker / image
  final String mediaType;
  final String? voicePath;
  final String? transcript;
  final int createdAt;

  /// 已读时刻。只有收到的消息才需要它，自己发出去的为 null。
  final int? readAt;
  final int? deletedAt;
  final String scope;
  const PrivateMessageRow({
    required this.id,
    required this.personaId,
    required this.direction,
    required this.content,
    required this.mediaType,
    this.voicePath,
    this.transcript,
    required this.createdAt,
    this.readAt,
    this.deletedAt,
    required this.scope,
  });
