class TopicRow extends DataClass implements Insertable<TopicRow> {
  final String id;
  final String name;
  final String description;

  /// 热度。由帖子数、互动数算出来，缓存成整数好排序；
  /// 怎么算的写在计算它的那处（B6），不在这里。
  final int heat;

  /// 内置话题从 assets 播种，不可删；用户新建的可以删。
  final bool isBuiltIn;
  final int createdAt;
  final int? deletedAt;
  final String scope;
  const TopicRow({
    required this.id,
    required this.name,
    required this.description,
    required this.heat,
    required this.isBuiltIn,
    required this.createdAt,
    this.deletedAt,
    required this.scope,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['description'] = Variable<String>(description);
    map['heat'] = Variable<int>(heat);
    map['is_built_in'] = Variable<bool>(isBuiltIn);
    map['created_at'] = Variable<int>(createdAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<int>(deletedAt);
    }
    map['scope'] = Variable<String>(scope);
    return map;
  }

  TopicsCompanion toCompanion(bool nullToAbsent) {
    return TopicsCompanion(
      id: Value(id),
      name: Value(name),
      description: Value(description),
      heat: Value(heat),
      isBuiltIn: Value(isBuiltIn),
      createdAt: Value(createdAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      scope: Value(scope),
    );
  }

  factory TopicRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return TopicRow(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      description: serializer.fromJson<String>(json['description']),
      heat: serializer.fromJson<int>(json['heat']),
      isBuiltIn: serializer.fromJson<bool>(json['isBuiltIn']),
      createdAt: serializer.fromJson<int>(json['createdAt']),
      deletedAt: serializer.fromJson<int?>(json['deletedAt']),
      scope: serializer.fromJson<String>(json['scope']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'name': serializer.toJson<String>(name),
      'description': serializer.toJson<String>(description),
      'heat': serializer.toJson<int>(heat),
      'isBuiltIn': serializer.toJson<bool>(isBuiltIn),
      'createdAt': serializer.toJson<int>(createdAt),
      'deletedAt': serializer.toJson<int?>(deletedAt),
      'scope': serializer.toJson<String>(scope),
    };
  }

  TopicRow copyWith({
    String? id,
    String? name,
    String? description,
    int? heat,
    bool? isBuiltIn,
    int? createdAt,
    Value<int?> deletedAt = const Value.absent(),
    String? scope,
  }) => TopicRow(
    id: id ?? this.id,
    name: name ?? this.name,
    description: description ?? this.description,
    heat: heat ?? this.heat,
    isBuiltIn: isBuiltIn ?? this.isBuiltIn,
    createdAt: createdAt ?? this.createdAt,
    deletedAt: deletedAt.present ? deletedAt.value : this.deletedAt,
    scope: scope ?? this.scope,
  );
  TopicRow copyWithCompanion(TopicsCompanion data) {
    return TopicRow(
      id: data.id.present ? data.id.value : this.id,
      name: data.name.present ? data.name.value : this.name,
      description: data.description.present
          ? data.description.value
          : this.description,
      heat: data.heat.present ? data.heat.value : this.heat,
      isBuiltIn: data.isBuiltIn.present ? data.isBuiltIn.value : this.isBuiltIn,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      deletedAt: data.deletedAt.present ? data.deletedAt.value : this.deletedAt,
      scope: data.scope.present ? data.scope.value : this.scope,
    );
  }

  @override
  String toString() {
    return (StringBuffer('TopicRow(')
          ..write('id: $id, ')
          ..write('name: $name, ')
          ..write('description: $description, ')
          ..write('heat: $heat, ')
          ..write('isBuiltIn: $isBuiltIn, ')
          ..write('createdAt: $createdAt, ')
          ..write('deletedAt: $deletedAt, ')
          ..write('scope: $scope')
          ..write(')'))
        .toString();
  }

