class StickerRow extends DataClass implements Insertable<StickerRow> {
  final String id;

  /// 展示名，也是图片缺失时的文字兜底内容。
  final String name;
  final String category;

  /// AI 选表情时看的标签（JSON 数组）。没标签的表情包不会进 AI 目录。
  final String tags;

  /// asset / file
  final String source;
  final String path;
  final bool isUser;
  final bool isBuiltin;
  final int? createdAt;
  final int? deletedAt;
  final String scope;
  const StickerRow({
    required this.id,
    required this.name,
    required this.category,
    required this.tags,
    required this.source,
    required this.path,
    required this.isUser,
    required this.isBuiltin,
    this.createdAt,
    this.deletedAt,
    required this.scope,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['name'] = Variable<String>(name);
    map['category'] = Variable<String>(category);
    map['tags'] = Variable<String>(tags);
    map['source'] = Variable<String>(source);
    map['path'] = Variable<String>(path);
    map['is_user'] = Variable<bool>(isUser);
    map['is_builtin'] = Variable<bool>(isBuiltin);
    if (!nullToAbsent || createdAt != null) {
      map['created_at'] = Variable<int>(createdAt);
    }
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<int>(deletedAt);
    }
    map['scope'] = Variable<String>(scope);
    return map;
  }

  StickersCompanion toCompanion(bool nullToAbsent) {
    return StickersCompanion(
      id: Value(id),
      name: Value(name),
      category: Value(category),
      tags: Value(tags),
      source: Value(source),
      path: Value(path),
      isUser: Value(isUser),
      isBuiltin: Value(isBuiltin),
      createdAt: createdAt == null && nullToAbsent
          ? const Value.absent()
          : Value(createdAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      scope: Value(scope),
    );
  }

  factory StickerRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return StickerRow(
      id: serializer.fromJson<String>(json['id']),
      name: serializer.fromJson<String>(json['name']),
      category: serializer.fromJson<String>(json['category']),
      tags: serializer.fromJson<String>(json['tags']),
      source: serializer.fromJson<String>(json['source']),
      path: serializer.fromJson<String>(json['path']),
