class ModelConfigRow extends DataClass implements Insertable<ModelConfigRow> {
  final String id;

  /// 预设服务商标识：openai / deepseek / qwen / zhipu / custom
  final String provider;

  /// 展示名，用户可改
  final String label;

  /// OpenAI 兼容的 base url（不带 /chat/completions）
  final String baseUrl;
  final String model;

  /// 用途：chat（对话）/ image（文生图）。
  ///
  /// 两者是分开配的，也允许只配其中之一——文生图比对话贵一个量级，
  /// 用户完全可能只想用便宜的那个。
  final String kind;

  /// 这条对话模型能不能直接收图片（v24）。
  /// 关着的时候私信图片不会塞进请求，避免整轮 400。
  final bool supportsVision;

  /// 当前启用中的那一条为 true（**同一用途**里只允许一条）
  final bool enabled;
  final int createdAt;
  final int updatedAt;
  const ModelConfigRow({
    required this.id,
    required this.provider,
    required this.label,
    required this.baseUrl,
    required this.model,
    required this.kind,
    required this.supportsVision,
    required this.enabled,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['provider'] = Variable<String>(provider);
    map['label'] = Variable<String>(label);
    map['base_url'] = Variable<String>(baseUrl);
    map['model'] = Variable<String>(model);
    map['kind'] = Variable<String>(kind);
    map['supports_vision'] = Variable<bool>(supportsVision);
    map['enabled'] = Variable<bool>(enabled);
    map['created_at'] = Variable<int>(createdAt);
    map['updated_at'] = Variable<int>(updatedAt);
    return map;
  }

  ModelConfigsCompanion toCompanion(bool nullToAbsent) {
    return ModelConfigsCompanion(
      id: Value(id),
      provider: Value(provider),
      label: Value(label),
      baseUrl: Value(baseUrl),
      model: Value(model),
      kind: Value(kind),
      supportsVision: Value(supportsVision),
      enabled: Value(enabled),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory ModelConfigRow.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return ModelConfigRow(
      id: serializer.fromJson<String>(json['id']),
      provider: serializer.fromJson<String>(json['provider']),
      label: serializer.fromJson<String>(json['label']),
      baseUrl: serializer.fromJson<String>(json['baseUrl']),
      model: serializer.fromJson<String>(json['model']),
      kind: serializer.fromJson<String>(json['kind']),
      supportsVision: serializer.fromJson<bool>(json['supportsVision']),
      enabled: serializer.fromJson<bool>(json['enabled']),
      createdAt: serializer.fromJson<int>(json['createdAt']),
      updatedAt: serializer.fromJson<int>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'provider': serializer.toJson<String>(provider),
      'label': serializer.toJson<String>(label),
      'baseUrl': serializer.toJson<String>(baseUrl),
      'model': serializer.toJson<String>(model),
      'kind': serializer.toJson<String>(kind),
